/// component or hook.
///
/// Hooks must be called from the top level of a React component or a custom
/// hook. Being defined inside a callback or a nested helper function within a
/// component or hook breaks that requirement, so such functions are considered
/// nested.
///
/// A component or hook that is itself defined inside another function (for
/// example inside a test function body) is *not* considered nested, because
/// the enclosing function is neither a component nor a hook.
fn is_nested_function(function: &AnyJsFunctionOrMethod) -> bool {
    let Some(parent) = function.syntax().parent() else {
        return false;
    };

    parent
        .ancestors()
        .find_map(AnyJsFunctionOrMethod::cast)
        .is_some_and(|enclosing_function| is_react_component_or_hook(&enclosing_function))
