            .map(|token| token.token_text_trimmed()),
        AnyJsFunctionOrMethod::JsMethodObjectMember(member) => {
            member.name().ok().and_then(|name| name.name())
        }
    };

    name.is_some_and(|name| {
        let name = name.text();
        is_react_component(name) || is_react_hook(name)
    })
